function updateUserUI() {
    // Check if user is logged in
    fetch('google-login-handler.php')
        .then(response => response.json())
        .then(data => {
            if (data.loggedIn) {
                // Find all signup buttons
                const signupButtons = document.querySelectorAll('.sign-up-btn');
                signupButtons.forEach(button => {
                    // Create name display element
                    const nameDisplay = document.createElement('div');
                    nameDisplay.className = 'user-name-display';
                    nameDisplay.textContent = `${data.user.name} ${data.user.lastname}`;
                    nameDisplay.style.color = '#fff'; // Match your existing text color
                    nameDisplay.style.display = 'flex';
                    nameDisplay.style.alignItems = 'center';
                    
                    // Add user icon
                    const userIcon = document.createElement('i');
                    userIcon.className = 'fa-solid fa-user';
                    userIcon.style.marginRight = '7px';
                    nameDisplay.prepend(userIcon);
                    
                    // Replace button with name
                    button.parentNode.replaceChild(nameDisplay, button);
                });
            }
        });
}

// Run when page loads
document.addEventListener('DOMContentLoaded', updateUserUI);